     3	// SPEC X4. The whole stack runs on its own ports, so a `pnpm dev` session (which may point at the
     4	// real Weatherstack) is never reused: the API only ever talks to the local stub.
     5	const STUB_PORT = 4999;
     6	const API_PORT = 4100;
     7	const WEB_PORT = 5174;
     8	
     9	// Commands call local binaries with `exec` rather than `pnpm exec`: pnpm starts its child in a new
    10	// process group, which Playwright's teardown can't reach, so servers outlive the run and it hangs.
    11	const shutdown = { signal: 'SIGTERM', timeout: 2000 } as const;
