    13	// Same database as the integration tests, never the dev one (CLAUDE.md "Tests"). Those tests
    14	// truncate it, so never run the two at once; `pnpm verify` runs them one after the other.
    15	const DATABASE_URL =
    16	  process.env['TEST_DATABASE_URL'] ??
    17	  'postgresql://[REDACTED]@localhost:5433/covertree_test';
    18	if (!DATABASE_URL.includes(':5433/')) {
    19	  throw new Error(`Refusing to run e2e against a non-test database: ${DATABASE_URL}`);
    20	}
