    27	  reporter: process.env['CI'] ? 'github' : 'list',
    28	  use: {
    29	    baseURL: `http://127.0.0.1:${WEB_PORT}`,
    30	    trace: 'retain-on-failure',
    31	  },
    32	  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
    33	  webServer: [
    34	    {
    35	      name: 'weatherstack-stub',
    36	      command: 'exec node e2e/weatherstack-stub.mjs',
    37	      url: `http://localhost:${STUB_PORT}/current`,
    38	      env: { WEATHERSTACK_STUB_PORT: String(STUB_PORT) },
    39	      reuseExistingServer: false,
    40	      gracefulShutdown: shutdown,
    41	    },
    42	    {
    43	      name: 'api',
    44	      command:
    45	        'node_modules/.bin/prisma migrate deploy && exec node_modules/.bin/tsx src/server.ts',
    46	      cwd: '../api',
    47	      url: `http://localhost:${API_PORT}/graphql`,
