     1	import { createGraphQLError } from 'graphql-yoga';
     2	import type {
     3	  Resolvers,
     4	  ResolversTypes,
     5	  WeatherFailureReason,
     6	} from '../__generated__/resolvers-types.ts';
     7	
     8	const WEATHER_MESSAGES: Record<WeatherFailureReason, string> = {
     9	  NETWORK: 'Could not reach the weather service. The property was not created.',
    10	  TIMEOUT: 'The weather service did not respond in time. The property was not created.',
    11	  HTTP_ERROR: 'The weather service returned an error. The property was not created.',
    12	  UPSTREAM_ERROR: 'The weather service rejected the request. The property was not created.',
    13	  INVALID_RESPONSE: 'The weather service returned unusable data. The property was not created.',
    14	  LOCATION_MISMATCH:
    15	    'The weather service resolved this zip code outside the USA. The property was not created.',
    16	};
    17	
    18	export const propertyResolvers: Resolvers = {
    19	  Query: {
    20	    async properties(_parent, { filter, orderBy }, { services }) {
    21	      const result = await services.listProperties({ createdAt: orderBy?.createdAt, filter });
    22	      if (result.kind === 'invalidFilter') {
    23	        // S3.6 — a bad filter is an error, never an empty list.
    24	        throw createGraphQLError(result.message, { extensions: { code: 'BAD_USER_INPUT' } });
    25	      }
    26	      return result.properties;
    27	    },
    28	
    29	    property: (_parent, { id }, { services }) => services.getProperty(id),
    30	  },
    31	
    32	  Mutation: {
    33	    async createProperty(_parent, { input }, { services }) {
    34	      const result = await services.createProperty(input);
    35	      switch (result.kind) {
    36	        case 'created':
    37	          return { __typename: 'CreatePropertySuccess', property: result.property };
    38	        case 'invalidInput':
    39	          return {
    40	            __typename: 'InvalidInputError',
    41	            message: 'Some fields are invalid.',
    42	            fieldErrors: result.fieldErrors,
    43	          };
    44	        case 'duplicate':
    45	          return {
    46	            __typename: 'DuplicatePropertyError',
    47	            message: 'A property with this address already exists.',
    48	            existingPropertyId: result.existingPropertyId,
    49	          };
    50	        case 'weatherUnavailable':
    51	          return {
    52	            __typename: 'WeatherUnavailableError',
    53	            message: WEATHER_MESSAGES[result.reason],
    54	            reason: result.reason,
    55	          };
    56	      }
    57	    },
    58	
    59	    async deleteProperty(_parent, { id }, { services }) {
    60	      const result = await services.deleteProperty(id);
    61	      return result.kind === 'deleted'
    62	        ? { __typename: 'DeletePropertySuccess', id: result.id }
    63	        : { __typename: 'PropertyNotFoundError', message: 'Property not found.', id: result.id };
    64	    },
    65	  },
    66	
    67	  Property: {
    68	    // Stored as the validated Weatherstack `current` object (snake_case), see create-property service.
    69	    weatherData: (property) => property.weatherData as unknown as ResolversTypes['Weather'],
    70	  },
    71	
    72	  Weather: {
    73	    observationTime: (w) => w.observation_time,
    74	    feelsLike: (w) => w.feelslike,
    75	    weatherCode: (w) => w.weather_code ?? null,
    76	    weatherDescriptions: (w) => w.weather_descriptions.map((text) => text.trim()),
    77	    weatherIcons: (w) => w.weather_icons,
    78	    windSpeed: (w) => w.wind_speed,
    79	    windDegree: (w) => w.wind_degree ?? null,
    80	    windDir: (w) => w.wind_dir,
    81	    uvIndex: (w) => w.uv_index ?? null,
    82	    isDay: (w) => (w.is_day === undefined ? null : w.is_day === 'yes'),
    83	  },
    84	};
=== apps/api/src/services/create-property.service.ts
     1	import { z } from 'zod';
     2	import type {
     3	  Address,
     4	  PropertyRecord,
     5	  PropertyRepository,
     6	  USState,
     7	} from '../repositories/property.repository.ts';
     8	import type { WeatherFailureReason, WeatherstackClient } from '../weatherstack/client.ts';
     9	
    10	export interface CreatePropertyInput {
    11	  street: string;
    12	  city: string;
    13	  state: USState;
    14	  zipCode: string;
    15	}
    16	
    17	export interface FieldError {
    18	  field: keyof CreatePropertyInput;
    19	  message: string;
    20	}
    21	
    22	export type CreatePropertyResult =
    23	  | { kind: 'created'; property: PropertyRecord }
    24	  | { kind: 'invalidInput'; fieldErrors: FieldError[] }
    25	  | { kind: 'duplicate'; existingPropertyId: string }
    26	  | { kind: 'weatherUnavailable'; reason: WeatherFailureReason };
    27	
    28	export type CreateProperty = (input: CreatePropertyInput) => Promise<CreatePropertyResult>;
    29	
    30	/** S5.6 — Weatherstack names territories only in `region`, so one list covers every USState. */
    31	const US_COUNTRIES: ReadonlySet<string> = new Set([
    32	  'USA United States of America',
    33	  'United States of America',
    34	]);
    35	
    36	/** S5.3 — rules GraphQL can't express. `state` is already a valid enum value. */
    37	const Input = z.object({
    38	  street: z
    39	    .string()
    40	    .trim()
    41	    .min(1, 'Street is required.')
    42	    .max(200, 'Street must be at most 200 characters.'),
    43	  city: z
    44	    .string()
    45	    .trim()
    46	    .min(1, 'City is required.')
    47	    .max(100, 'City must be at most 100 characters.'),
    48	  zipCode: z.string().regex(/^\d{5}$/, 'Zip code must be exactly 5 digits.'),
    49	});
    50	
    51	export interface CreatePropertyDeps {
    52	  properties: Pick<PropertyRepository, 'findByAddress' | 'insert'>;
    53	  weatherstack: WeatherstackClient;
    54	  logger?: Pick<Console, 'warn'>;
    55	}
    56	
    57	/**
    58	 * S5 — validate → duplicate check → one Weatherstack call → persist. Anything short of complete
    59	 * weather data aborts before writing (ADR-0004).
    60	 */
    61	export function createPropertyService({
    62	  properties,
    63	  weatherstack,
    64	  logger = console,
    65	}: CreatePropertyDeps): CreateProperty {
    66	  return async (input) => {
    67	    const parsed = Input.safeParse(input);
    68	    if (!parsed.success) {
    69	      return {
    70	        kind: 'invalidInput',
    71	        fieldErrors: parsed.error.issues.map((issue) => ({
    72	          field: issue.path[0] as FieldError['field'],
    73	          message: issue.message,
    74	        })),
    75	      };
    76	    }
    77	
    78	    const address: Address = { ...parsed.data, state: input.state };
    79	    const existing = await properties.findByAddress(address);
    80	    if (existing) return { kind: 'duplicate', existingPropertyId: existing.id };
    81	
    82	    const lookup = await weatherstack.current(`${address.zipCode}, ${address.state}, USA`);
    83	    if (!lookup.ok) {
    84	      logger.warn(`Weatherstack lookup failed: ${lookup.reason} (${lookup.detail})`);
    85	      return { kind: 'weatherUnavailable', reason: lookup.reason };
    86	    }
    87	
    88	    const { location, current } = lookup.response;
    89	    if (!US_COUNTRIES.has(location.country)) {
    90	      logger.warn(`Weatherstack resolved ${address.zipCode} outside the USA: ${location.country}`);
    91	      return { kind: 'weatherUnavailable', reason: 'LOCATION_MISMATCH' };
    92	    }
    93	
    94	    const inserted = await properties.insert({
    95	      ...address,
    96	      weatherData: current,
    97	      lat: location.lat,
    98	      long: location.lon,
    99	    });
   100	    return inserted.ok
   101	      ? { kind: 'created', property: inserted.property }
   102	      : { kind: 'duplicate', existingPropertyId: inserted.duplicateOf };
   103	  };
   104	}
