     1	import { z } from 'zod';
     2	import type {
     3	  PropertyFilter,
     4	  PropertyRecord,
     5	  PropertyRepository,
     6	  SortDirection,
     7	  USState,
     8	} from '../repositories/property.repository.ts';
     9	
    10	export interface ListPropertiesOptions {
    11	  /** S2.1 — newest first when omitted. */
    12	  createdAt?: 'ASC' | 'DESC' | null;
    13	  filter?: {
    14	    city?: string | null;
    15	    zipCode?: string | null;
    16	    state?: USState | null;
    17	  } | null;
    18	}
    19	
    20	export type ListPropertiesResult =
    21	  { kind: 'listed'; properties: PropertyRecord[] } | { kind: 'invalidFilter'; message: string };
    22	
    23	export type ListProperties = (options?: ListPropertiesOptions) => Promise<ListPropertiesResult>;
    24	
    25	const DIRECTION: Record<'ASC' | 'DESC', SortDirection> = { ASC: 'asc', DESC: 'desc' };
    26	
    27	/** Trimmed; empty or whitespace-only means "no constraint" (S3.4). */
    28	const optionalText = z
    29	  .string()
    30	  .nullish()
    31	  .transform((value) => value?.trim() || undefined);
    32	
    33	const Filter = z.object({
    34	  city: optionalText,
    35	  // S3.5/S3.6 — exact 5 digits when present.
    36	  zipCode: optionalText.refine((zip) => zip === undefined || /^\d{5}$/.test(zip), {
    37	    message: 'Zip code filter must be exactly 5 digits.',
    38	  }),
    39	  state: z
    40	    .custom<USState>()
    41	    .nullish()
    42	    .transform((state) => state ?? undefined),
    43	});
    44	
    45	/** S1–S3 — reads only; never touches Weatherstack (S1.3). */
    46	export function listPropertiesService({
    47	  properties,
    48	}: {
    49	  properties: Pick<PropertyRepository, 'list'>;
    50	}): ListProperties {
    51	  return async ({ createdAt, filter } = {}) => {
    52	    const parsed = Filter.safeParse(filter ?? {});
    53	    if (!parsed.success) {
    54	      return { kind: 'invalidFilter', message: parsed.error.issues[0]!.message };
    55	    }
    56	    const normalized: PropertyFilter = parsed.data;
    57	    return {
    58	      kind: 'listed',
    59	      properties: await properties.list({
    60	        direction: DIRECTION[createdAt ?? 'DESC'],
    61	        filter: normalized,
    62	      }),
    63	    };
    64	  };
    65	}
