    28	export type CreateProperty = (input: CreatePropertyInput) => Promise<CreatePropertyResult>;
    29	
    30	/** S5.6 — Weatherstack names territories only in `region`, so one list covers every USState. */
    31	const US_COUNTRIES: ReadonlySet<string> = new Set([
