    43	  city: z
    44	    .string()
    45	    .trim()
    46	    .min(1, 'City is required.')
    47	    .max(100, 'City must be at most 100 characters.'),
    48	  zipCode: z.string().regex(/^\d{5}$/, 'Zip code must be exactly 5 digits.'),
    49	});
