     8	/** The address that identifies a property; duplicates are exact matches on all four (S5.4). */
     9	export interface Address {
    10	  street: string;
    11	  city: string;
    12	  state: USState;
    13	  zipCode: string;
    14	}
    15	
    16	export interface NewProperty extends Address {
