815	    17	 * than sent to the API, which would reject the whole query (S3.6, S3.7).
816	    18	 */
817	    19	export function readListParams(params: URLSearchParams): ListParams {
818	    20	  const zipCode = params.get('zip')?.trim() ?? '';
819	    21	  const state = params.get('state') ?? '';
820	    22	  return {
821	    23	    filter: {
822	    24	      ...NO_FILTER,
823	    25	      city: params.get('city') ?? '',
824	    26	      zipCode: /^\d{5}$/.test(zipCode) ? zipCode : '',
825	    27	      state: STATES.has(state) ? state : '',
