    10	import { NativeSelect, NativeSelectOption } from '@/components/ui/native-select';
    11	import { USState } from '@/gql/graphql';
    12	import { CreatePropertyMutation } from './create-property.mutation';
    13	import {
    14	  validateProperty,
    15	  type PropertyFormErrors,
    16	  type PropertyFormValues,
    17	} from './validate-property';
    18	
    19	const STATES = Object.values(USState);
    20	const EMPTY: PropertyFormValues = { street: '', city: '', state: '', zipCode: '' };
    21	
    22	type Notice =
    23	  | { kind: 'weather'; message: string }
    24	  | { kind: 'duplicate'; message: string; existingPropertyId: string }
    25	  | { kind: 'error'; message: string };
    26	
    27	/** S5.8 — create a property; every CreatePropertyResult member has a visible outcome. */
    28	export function CreatePropertyForm() {
    29	  const navigate = useNavigate();
    30	  const [values, setValues] = useState(EMPTY);
    31	  const [errors, setErrors] = useState<PropertyFormErrors>({});
    32	  const [notice, setNotice] = useState<Notice | null>(null);
    33	  const [createProperty, { loading }] = useMutation(CreatePropertyMutation);
    34	
    35	  const update = (field: keyof PropertyFormValues) => (value: string) => {
    36	    setValues((current) => ({ ...current, [field]: value }));
    37	    setErrors((current) => ({ ...current, [field]: undefined }));
    38	  };
    39	
    40	  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    41	    event.preventDefault();
    42	    setNotice(null);
    43	    const clientErrors = validateProperty(values);
    44	    setErrors(clientErrors);
    45	    if (Object.keys(clientErrors).length > 0) return;
    46	
    47	    try {
    48	      const { data } = await createProperty({
    49	        variables: { input: { ...values, state: values.state as USState } },
    50	      });
    51	      const result = data?.createProperty;
    52	      switch (result?.__typename) {
    53	        case 'CreatePropertySuccess':
    54	          toast.success('Property created', { description: values.street.trim() });
    55	          await navigate(`/properties/${result.property.id}`);
    56	          return;
    57	        case 'InvalidInputError':
    58	          setErrors(
    59	            Object.fromEntries(result.fieldErrors.map(({ field, message }) => [field, message])),
    60	          );
    61	          return;
    62	        case 'DuplicatePropertyError':
    63	          setNotice({ kind: 'duplicate', ...result });
    64	          return;
    65	        case 'WeatherUnavailableError':
    66	          setNotice({ kind: 'weather', message: result.message });
    67	          return;
    68	        default:
    69	          setNotice({ kind: 'error', message: 'Unexpected response from the server.' });
    70	      }
    71	    } catch {
    72	      setNotice({ kind: 'error', message: 'Could not reach the server. Please try again.' });
    73	    }
    74	  }
    75	
    76	  return (
    77	    <form onSubmit={onSubmit} noValidate className="grid gap-5">
    78	      {notice && <NoticeAlert notice={notice} />}
    79	
    80	      <Field id="street" label="Street" error={errors.street}>
    81	        <Input
    82	          id="street"
    83	          value={values.street}
    84	          onChange={(e) => update('street')(e.target.value)}
    85	          placeholder="15528 E Golden Eagle Blvd"
    86	          aria-invalid={!!errors.street}
    87	          aria-describedby={errors.street ? 'street-error' : undefined}
    88	        />
    89	      </Field>
    90	
    91	      <Field id="city" label="City" error={errors.city}>
    92	        <Input
    93	          id="city"
    94	          value={values.city}
    95	          onChange={(e) => update('city')(e.target.value)}
    96	          placeholder="Fountain Hills"
    97	          aria-invalid={!!errors.city}
    98	          aria-describedby={errors.city ? 'city-error' : undefined}
    99	        />
   100	      </Field>
   101	
   102	      <div className="grid grid-cols-2 items-start gap-4">
   103	        <Field id="state" label="State" error={errors.state}>
   104	          <NativeSelect
   105	            id="state"
   106	            value={values.state}
   107	            onChange={(e) => update('state')(e.target.value)}
   108	            aria-invalid={!!errors.state}
   109	            aria-describedby={errors.state ? 'state-error' : undefined}
   110	            className="w-full"
   111	          >
   112	            <NativeSelectOption value="">Select…</NativeSelectOption>
   113	            {STATES.map((state) => (
   114	              <NativeSelectOption key={state} value={state}>
   115	                {state}
   116	              </NativeSelectOption>
   117	            ))}
   118	          </NativeSelect>
   119	        </Field>
   120	
   121	        <Field id="zipCode" label="Zip code" error={errors.zipCode}>
   122	          <Input
   123	            id="zipCode"
   124	            value={values.zipCode}
   125	            onChange={(e) => update('zipCode')(e.target.value)}
   126	            placeholder="85268"
   127	            inputMode="numeric"
   128	            maxLength={5}
   129	            aria-invalid={!!errors.zipCode}
   130	            aria-describedby={errors.zipCode ? 'zipCode-error' : undefined}
   131	          />
   132	        </Field>
   133	      </div>
   134	
   135	      <Button type="submit" disabled={loading} className="justify-self-start">
   136	        {loading ? 'Creating…' : 'Create property'}
   137	      </Button>
   138	    </form>
   139	  );
   140	}
   141	
   142	function Field({
   143	  id,
   144	  label,
   145	  error,
   146	  children,
   147	}: {
   148	  id: string;
   149	  label: string;
   150	  error: string | undefined;
   151	  children: React.ReactNode;
   152	}) {
   153	  return (
   154	    <div className="grid gap-2">
   155	      <Label htmlFor={id}>{label}</Label>
   156	      {children}
   157	      {error && (
   158	        <p id={`${id}-error`} className="text-sm text-destructive">
   159	          {error}
   160	        </p>
   161	      )}
   162	    </div>
   163	  );
   164	}
   165	
   166	function NoticeAlert({ notice }: { notice: Notice }) {
   167	  if (notice.kind === 'weather') {
   168	    return (
   169	      <Alert variant="destructive">
   170	        <CloudOff />
   171	        <AlertTitle>Weather data unavailable, property not created</AlertTitle>
   172	        <AlertDescription>{notice.message}</AlertDescription>
   173	      </Alert>
   174	    );
   175	  }
   176	  if (notice.kind === 'duplicate') {
   177	    return (
   178	      <Alert>
   179	        <AlertTitle>{notice.message}</AlertTitle>
   180	        <AlertDescription>
   181	          <Link to={`/properties/${notice.existingPropertyId}`} className="underline">
   182	            View the existing property
   183	          </Link>
   184	        </AlertDescription>
   185	      </Alert>
   186	    );
   187	  }
   188	  return (
   189	    <Alert variant="destructive">
   190	      <AlertTitle>Something went wrong</AlertTitle>
   191	      <AlertDescription>{notice.message}</AlertDescription>
   192	    </Alert>
   193	  );
   194	}
